<?php
namespace App\Http\Controllers;
use App\Models\{Document,DocumentMetadata,DocumentType,Unit,Workflow}; use App\Services\WorkflowService; use Illuminate\Http\Request; use Illuminate\Support\Str;
class InternalDocumentController extends Controller {
 public function create(string $type){$documentType=$this->type($type);abort_unless(auth()->user()->hasPermission('create documents'),403);return view('internal_documents.form',['type'=>$documentType,'units'=>Unit::orderBy('name')->get(),'workflows'=>Workflow::where('document_type_id',$documentType->id)->where('is_active',true)->get()]);}
 public function store(Request $request,string $type,WorkflowService $engine){$documentType=$this->type($type);$data=$request->validate(['unit_id'=>['nullable','exists:units,id'],'subject'=>['required','max:255'],'content'=>['required'],'workflow_id'=>[$documentType->code==='ASSIGNMENT'?'required':'nullable','exists:workflows,id'],'metadata'=>['nullable','array'],'attachment'=>['nullable','file','max:10240']]);$doc=Document::create(['document_type_id'=>$documentType->id,'unit_id'=>$data['unit_id'],'creator_id'=>$request->user()->id,'subject'=>$data['subject'],'content'=>$data['content'],'status'=>'DRAFT','uuid'=>(string)Str::uuid(),'verification_token'=>Str::random(48)]);$metadata=$data['metadata']??[];if($request->hasFile('attachment'))$metadata['attachment_path']=$request->file('attachment')->store('attachments','local');DocumentMetadata::create(['document_id'=>$doc->id,'data'=>$metadata]);if(!empty($data['workflow_id']))$engine->start($doc,Workflow::findOrFail($data['workflow_id']),$request->user());return redirect()->route('documents.show',$doc)->with('success','Dokumen berhasil dibuat.');}
 private function type(string $type):DocumentType{return DocumentType::where('code',strtoupper($type))->firstOrFail();}
}
